    facts: {
      de: ["Gegründet 1838 von Voortrekkern.", "Startpunkt des berühmten Comrades Marathon."],
      hu: ["Voortrekker telepesek alapították 1838-ban.", "A híres Comrades Maraton rajtjának helyszíne."],
      ro: ["Fondată în 1838 de coloniștii Voortrekker.", "Punct de plecare pentru celebrul Maraton Comrades."],
      en: ["Founded in 1838 by Voortrekkers.", "Starting point of the famous Comrades Marathon."],
      es: ["Fundada en 1838 por los Voortrekkers.", "Punto de partida del famoso Comrades Marathon."],
      pt: ["Fundada em 1838 pelos Voortrekkers.", "Ponto de partida da famosa Comrades Marathon."],
      fr: ["Fondée en 1838 par les Voortrekkers.", "Point de départ du célèbre Comrades Marathon."],
    }, image: "/poi-images/southafrica-pietermaritzburg-cities-v2.webp",
    descriptionAdvanced: {
      de: "Pietermaritzburg, oft liebevoll „PMB“ genannt, ist die Hauptstadt der Provinz KwaZulu-Natal und eine Stadt mit einer außergewöhnlich reichen und komplexen Geschichte. Gegründet wurde sie 1838 von den Voortrekkern nach dem Sieg am Blood River und benannt nach den Anführern Piet Retief und Gert Maritz. Geografisch liegt die Stadt in einer Schüsselformation, umgeben von sanften Hügeln und dem Msunduzi River, was ihr im Sommer ein feuchtheißes und im Winter ein nebliges Klima verleiht. Pietermaritzburg ist weltweit bekannt für seine gut erhaltene viktorianische Architektur, wobei das monumentale Rathaus aus rotem Backstein als eines der größten seiner Art auf der südlichen Erdkugel gilt. Ein Wendepunkt der Weltgeschichte ereignete sich 1893 am hiesigen Bahnhof, als Mahatma Gandhi wegen seiner Hautfarbe aus einem Erste-Klasse-Abteil geworfen wurde – ein Ereignis, das seinen Weg des gewaltlosen Widerstands prägte. Heute ist die Stadt ein bedeutendes Zentrum für Bildung, Verwaltung und Industrie. Die University of KwaZulu-Natal hat hier einen ihrer wichtigsten Standorte. Wirtschaftlich ist Pietermaritzburg ein Knotenpunkt für die Aluminiumverarbeitung, die Holzindustrie und die Textilproduktion. Sportlich genießt die Stadt Weltruf als Start- oder Zielort des legendären Comrades Marathon und des Dusi Canoe Marathon. Die botanischen Gärten der Stadt gehören zu den ältesten des Landes und zeigen eine beeindruckende Vielfalt an Azaleen und Kamelien. Pietermaritzburg bewahrt trotz seiner Modernisierung den Charme einer „Gartenstadt“ und dient als wichtiges Bindeglied zwischen der Hafenstadt Durban und dem südafrikanischen Hinterland.",
      hu: "Pietermaritzburg KwaZulu-Natal tartomány fővárosa, amely Dél-Afrika egyik legrégebbi és legkarakteresebb települése. A várost 1838-ban alapították a búr telepesek (voortrekkerek), nevét pedig két vezetőjükről, Piet Retiefről és Gert Maritzról kapta. A város egy festői völgyben fekszik, amelyet a Msunduzi-folyó szel át, és dombos táj vesz körül. Pietermaritzburg építészeti öröksége lenyűgöző; vörös téglás viktoriánus épületei, különösen a városháza, amely a déli félteke legnagyobb ilyen típusú építménye, a brit gyarmati korszak pompáját idézik. Történelmi jelentőségét tovább növeli, hogy 1893-ban itt érte Mahatma Gandhit az az incidens a vasútállomáson, amely elindította őt az emberi jogi küzdelem útján. Napjainkban a város fontos közigazgatási és oktatási központ, itt található a KwaZulu-Natal Egyetem egyik jelentős campusa. Gazdaságában meghatározó az alumíniumgyártás, a faipar és az élelmiszer-feldolgozás, köszönhetően a környező fenyő- és eukaliptusz-ültetvényeknek. A sportvilágban Pietermaritzburg a Comrades Marathon egyik végpontjaként vált ismertté, amely a világ legnépszerűbb ultra-távfutó versenye. A város híres „kertváros” jellegéről, amit a KwaZulu-Natal Nemzeti Botanikus Kert és a számos virágos park is igazol. Az éghajlatot a meleg, párás nyarak és a hűvös, ködös telek jellemzik, ami kedvez a dús növényzetnek. Pietermaritzburg stratégiai elhelyezkedése a Durban-Johannesburg folyosón biztosítja a város folyamatos fejlődését és jelentőségét a modern Dél-Afrikában.",
      ro: "Pietermaritzburg, capitala provinciei KwaZulu-Natal, este un oraș cu o identitate distinctă, împletind moștenirea bură, britanică și indiană într-un peisaj urban fascinant. Fondat în 1838 de către buri, orașul a devenit ulterior un centru administrativ britanic major, lucru vizibil astăzi în arhitectura sa victoriană remarcabilă. Situat într-o depresiune naturală pe malurile râului Msunduzi, Pietermaritzburg este înconjurat de dealuri verzi care îi conferă un aspect pitoresc, deși clima poate fi extrem de umedă în timpul verii. Unul dintre cele mai importante repere istorice este statuia lui Mahatma Gandhi din centrul orașului, ridicată în memoria incidentului din 1893 când acesta a fost evacuat forțat dintr-un tren, eveniment ce a marcat începutul luptei sale împotriva discriminării. Economia orașului este diversificată, având sectoare industriale puternice în prelucrarea aluminiului, producția de mobilă și încălțăminte. Pietermaritzburg este, de asemenea, un centru de excelență academică, găzduind sediul Universității din KwaZulu-Natal. Evenimentele sportive internaționale, precum Maratonul Comrades și Maratonul de Canoe Dusi, atrag mii de participanți și spectatori anual, punând orașul pe harta sportivă mondială. Grădina Botanică Națională KwaZulu-Natal, fondată în 1872, este renumită pentru aleea sa spectaculoasă de platani și pentru conservarea plantelor indigene din estul Africii. Orașul servește ca un nod vital pe coridorul de transport N3, legând portul Durban de inima economică a țării, Johannesburg. Prin conservarea clădirilor sale istorice și adaptarea la cerințele moderne, Pietermaritzburg rămâne un simbol al continuității și diversității sud-africane.",
      en: "Pietermaritzburg, the capital of KwaZulu-Natal province, is a city of profound historical depth and architectural elegance. Established by the Voortrekkers in 1838 and named after leaders Piet Retief and Gert Maritz, the city later became a cornerstone of British colonial administration in the region. Nestled in a scenic basin along the Msunduzi River, it is often referred to as 'The City of Choice.' Its Victorian legacy is strikingly preserved in the red-brick buildings that line its streets, most notably the City Hall, which stands as the largest red-brick building in the Southern Hemisphere. Pietermaritzburg holds a unique place in global political history as the site of the 1893 railway station incident involving Mahatma Gandhi, which catalyzed his transformation into a leader of non-violent resistance. Today, the city is a major educational hub, hosting the main campus of the University of KwaZulu-Natal and several prestigious historic schools. The economy is driven by a mix of manufacturing—particularly aluminum and timber products—government services, and agriculture from the surrounding Midlands. Pietermaritzburg is also a world-renowned sporting destination, serving as the start or finish point for the grueling Comrades Marathon and the legendary Dusi Canoe Marathon. The KwaZulu-Natal National Botanical Garden showcases a magnificent collection of indigenous and exotic plants, reflecting the city's lush, subtropical environment. Strategically positioned on the N3 highway between Durban and Johannesburg, Pietermaritzburg remains a vital commercial and administrative link in South Africa’s eastern corridor.",
    },
