      ro: ["Capitala provinciei KwaZulu-Natal din 2004.", "Fondat în 1838 de buri, ulterior capturat de britanici.", "Clădirea Primăriei a fost finalizată în 1900 din cărămidă roșie.", "Sediul principal al Universității din KwaZulu-Natal.", "Situat la o altitudine de aproximativ 600 de metri.", "Gazduiește cea mai veche grădină botanică din provincie (1872).", "Centru major pentru industria prelucrării aluminiului (Hulamin).", "Temperaturile pot fi foarte ridicate în timpul verii (peste 35°C)."],
      en: ["Legislative capital of KwaZulu-Natal Province.", "Established in 1838 following the Great Trek.", "Features some of the world's best-preserved Victorian architecture.", "Site of Mahatma Gandhi's 1893 expulsion from a first-class train.", "Located in the hollow of the Msunduzi River valley.", "World-renowned for hosting the Comrades and Dusi marathons.", "Major industrial hub for timber, aluminum, and footwear.", "Elevation is approximately 1,969 feet above sea level."],
