      hu: ["Kelet-Fokföld tartomány székhelye 1994 óta.", "A város neve xhosza nyelven bivalyt jelent.", "A Ciskei bantusztán egykori fővárosa az apartheid idején.", "1992-ben 28 embert lőttek agyon a hírhedt mészárlás során.", "A Buffalo City metropolisz önkormányzat része.", "Gazdasága 90%-ban a közigazgatásra és közszolgáltatásokra épül.", "A tartományi parlament és a miniszterelnöki hivatal székhelye.", "King William's Town-tól mindössze pár percnyi autóútra fekszik."],
      ro: ["Capitala administrativă a provinciei Eastern Cape din Africa de Sud.", "Numele provine de la râul Buffalo care traversează regiunea.", "Fostă capitală a Ciskei între 1981 și 1994.", "Masacrul din 1992 a dus la moartea a 28 de persoane.", "Sediul Legislaturii Provinciale Eastern Cape se află aici.", "Face parte din municipalitatea metropolitană Buffalo City.", "Populația este formată majoritar din vorbitori de limba Xhosa.", "Altitudinea medie a orașului este de aproximativ 435 de metri."],
      en: ["Administrative capital of the Eastern Cape province.", "Named 'Bhisho' which means 'Buffalo' in the isiXhosa language.", "Established as the capital of the Ciskei homeland in the 1970s.", "Location of the historic Bhisho massacre in September 1992.", "Houses the provincial government and central administrative offices.", "Integrated with King William’s Town as a major urban hub.", "Geographically located in the foothills of the Amatola Mountains.", "Summer rainfall climate with average temperatures around 25°C."],
