    facts: {
      de: ["Gegründet 1884 und nach Thomas Upington benannt.", "Besitzt eine der längsten Landebahnen der Welt."],
      hu: ["1884-ben alapították, nevét Thomas Upingtonról kapta.", "A világ egyik leghosszabb kifutópályájával rendelkezik."],
      ro: ["Fondat în 1884 și numit după Thomas Upington.", "Are una dintre cele mai lungi piste de aterizare din lume."],
      en: ["Founded in 1884 and named after Thomas Upington.", "Has one of the longest aircraft runways in the world."],
      es: ["Fundada en 1884 y nombrada en honor a Thomas Upington.", "Posee una de las pistas de aterrizaje más largas del mundo."],
      pt: ["Fundada em 1884 e nomeada em honra de Thomas Upington.", "Possui uma das pistas de aterragem mais longas do mundo."],
      fr: ["Fondée en 1884 et nommée en l'honneur de Thomas Upington.", "Possède l'une des pistes d'atterrissage les plus longues du monde."],
    }, image: "/poi-images/southafrica-upington-cities-v2.webp",
    descriptionAdvanced: {
      de: "Upington liegt im Norden der Provinz Nordkap am Ufer des Oranje-Flusses und wurde 1871 ursprünglich als Missionsstation Olijvenhoutsdrift gegründet. 1884 wurde die Siedlung nach Sir Thomas Upington benannt und entwickelte sich schnell zum wirtschaftlichen und logistischen Zentrum der wasserarmen Region Kalahari. Trotz des extrem trockenen Wüstenklimas ermöglichen ausgedehnte Bewässerungssysteme entlang des Flusses eine hochproduktive Landwirtschaft, die besonders für Tafeltrauben, Sultaninen und Weinbau bekannt ist. Die Stadt beherbergt die Orange River Wine Cellars, eine der größten Weinkooperativen der Welt. Ein technisches Highlight ist der Flughafen von Upington, dessen Landebahn mit 4900 Metern eine der längsten der südlichen Hemisphäre ist und früher als Notlandeplatz für das NASA Space Shuttle diente. Heute ist die Stadt das wichtigste Tor für Touristen, die die spektakulären Augrabies-Wasserfälle oder den grenzüberschreitenden Kgalagadi-Transfrontier-Park besuchen möchten.",
      hu: "Upington az Északi-fok tartományban, az Oranje-folyó partján fekszik, és 1871-ben alapították Olijvenhoutsdrift néven missziós állomásként. 1884-ben nevezték át Sir Thomas Upington tiszteletére, és hamarosan a Kalahári régió kereskedelmi és mezőgazdasági központjává vált. A város környéki száraz, sivatagi éghajlatot a folyó vizével ellensúlyozzák, ami lehetővé tette a kiterjedt szőlőtermesztést és a világhírű mazsolagyártást. Itt található Dél-Afrika legnagyobb borászati szövetkezete, az Orange River Wine Cellars, amely jelentős exportot bonyolít. Upington repülőtere híres rendkívül hosszú, 4900 méteres kifutópályájáról, amelyet egykor a NASA űrrepülőgépeinek vészhelyzeti leszállóhelyeként is kijelöltek. A település stratégiai jelentőségű logisztikai csomópont és elengedhetetlen állomás az Augrabies-vízesés Nemzeti Park és a Kgalagadi Transfrontier Park felé utazók számára.",
      ro: "Upington este situat în provincia Northern Cape, pe malurile fluviului Orange, fiind fondat în 1871 ca stațiune misionară sub numele de Olijvenhoutsdrift. Orașul a fost redenumit în 1884 în onoarea lui Sir Thomas Upington și a devenit rapid principalul centru economic și logistic al regiunii aride Kalahari. Climatul deșertic dur este temperat de sistemele complexe de irigații alimentate de fluviul Orange, care susțin o industrie agricolă prosperă axată pe struguri de masă, stafide și vinificație. Upington găzduiește Orange River Wine Cellars, cea mai mare cooperativă viticolă din Africa de Sud și un exportator global major. Aeroportul orașului este remarcabil pentru pista sa de 4900 de metri, una dintre cele mai lungi din lume, desemnată în trecut ca loc de aterizare de urgență pentru navetele spațiale NASA. Orașul servește ca punct de intrare esențial pentru turiștii care explorează Cascada Augrabies și Parcul Transfrontalier Kgalagadi.",
      en: "Upington is situated in the Northern Cape province on the fertile banks of the Orange River and was established in 1871 as a mission station named Olijvenhoutsdrift. In 1884, it was renamed after Sir Thomas Upington and grew into the primary commercial and agricultural hub of the surrounding Kalahari desert region. The harsh arid climate is mitigated by extensive irrigation from the river, supporting a thriving sector focused on table grapes, dried fruit, and wine production. The city is home to the Orange River Wine Cellars, the largest wine cooperative in South Africa and a significant global exporter. Upington Airport is notable for its 4,900-meter runway, one of the longest in the Southern Hemisphere, which was once designated as an emergency landing site for NASA's Space Shuttle. Today, the city remains a vital logistical center and the main gateway for visitors to the Augrabies Falls National Park and the Kgalagadi Transfrontier Park.",
      es: "Upington se encuentra a orillas del río Oranje en la provincia de Northern Cape y es el centro económico de la región. La ciudad fue fundada en 1873 y lleva el nombre del político Thomas Upington. Es conocida por la viticultura y el cultivo de uvas de mesa, dátiles y nueces, gracias al riego del río Oranje. Upington es un nudo de transporte importante hacia Namibia y Botsuana. El cercano desierto del Kalahari y la cascada Augrabies son destinos turísticos conocidos.",
      pt: "Upington situa-se nas margens do rio Oranje, na província do Cabo do Norte, e é o centro económico da região. A cidade foi fundada em 1873 e tem o nome do político Thomas Upington. É conhecida pela viticultura e pelo cultivo de uvas de mesa, tâmaras e nozes, graças à irrigação do rio Oranje. Upington é um nó de transportes importante para a Namíbia e o Botsuana. O próximo deserto do Kalahari e a cascata Augrabies são destinos turísticos conhecidos.",
      fr: "Upington est située sur les rives de la rivière Oranje, dans la province du Cap-du-Nord, et est le centre économique de la région. La ville a été fondée en 1873 et porte le nom du politicien Thomas Upington. Elle est connue pour sa viticulture et la culture de raisins de table, de dattes et de noix, grâce à l'irrigation par la rivière Oranje. Upington est un nœud de transport important vers la Namibie et le Botswana. Le désert du Kalahari tout proche et la cascade Augrabies sont des destinations touristiques bien connues.",
    },
