      de: ["Gegründet 1871 als Olijvenhoutsdrift.", "Umbenannt nach Sir Thomas Upington im Jahr 1884.", "Besitzt eine 4900 m lange Landebahn für Notlandungen der NASA.", "Sitz der Orange River Wine Cellars, einer riesigen Kooperative.", "Wichtigstes Tor zum Kgalagadi Transfrontier Park.", "Zentrum der südafrikanischen Sultaninen-Produktion."],
