      pt: ["Springbok tem cerca de 12.000 habitantes (2011).", "A cidade foi fundada em 1852.", "A mineração de cobre terminou em 2003.", "A época de floração estende-se de agosto a outubro.", "O Museu de Namaqualand foi inaugurado em 1980.", "Springbok situa-se a 950 m acima do nível do mar."],
