      pt: ["A mina Sishen produz cerca de 40 milhões de toneladas de minério de ferro por ano.", "População: aprox. 15.000 habitantes.", "Fundação: 1968.", "Altitude: 1.000 m acima do nível do mar.", "Precipitação anual: aprox. 200 mm.", "Distância para Upington: aprox. 300 km."],
