      pt: ["Vryburg foi fundada em 1882.", "População: aprox. 25.000 habitantes.", "Altitude: 1.200 m acima do nível do mar.", "Área do distrito: 21.000 km².", "Produção de manganês na região: 1 milhão de toneladas anuais.", "Distância de Joanesburgo: aprox. 400 km."],
