      de: ["Älteste europäische Siedlung nördlich des Vaal-Flusses (1837)", "Erlebte 1886 einen massiven Goldrausch", "Zentrum einer bedeutenden Mais- und Getreideproduktion", "Fundort der mysteriösen 'Klerksdorp-Sphären' (Pyrophyllit-Kugeln)", "Verfügt über einen der größten Krankenhauskomplexe der Region", "Wichtigstes Handelszentrum im Distrikt Dr. Kenneth Kaunda"],
      hu: ["A Vaal-folyótól északra fekvő legrégebbi európai település (1837)", "1886-ban hatalmas aranyláz helyszíne volt", "A régió kiemelt kukorica- és gabonatermelő központja", "A rejtélyes 'Klerksdorp-gömbök' lelőhelye", "A régió egyik legnagyobb kórházkomplexumával rendelkezik", "A Dr. Kenneth Kaunda körzet legfontosabb kereskedelmi központja"],
      ro: ["Cea mai veche așezare europeană la nord de râul Vaal (1837)", "A experimentat o febră majoră a aurului în 1886", "Centru de producție important pentru porumb și cereale", "Locul unde s-au descoperit misterioasele „Sferelor de Klerksdorp”", "Găzduiește unul dintre cele mai mari complexe spitalicești regionale", "Principalul centru comercial din districtul Dr. Kenneth Kaunda"],
      en: ["Oldest European settlement north of the Vaal River, founded 1837", "Site of a major gold rush starting in 1886", "Major hub for maize and grain production in South Africa", "Famous for the 'Klerksdorp spheres' found in local mines", "Home to one of the largest regional hospital complexes", "Primary commercial and industrial hub for the Dr. Kenneth Kaunda District"],
      es: ["Klerksdorp fue fundada en 1837.", "Población: aprox. 190.000 habitantes.", "Producción de oro en la cuenca de Witwatersrand: históricamente significativa.", "Altitud: 1.320 m sobre el nivel del mar.", "Precipitación anual: aprox. 500 mm.", "Distancia a Johannesburgo: aprox. 180 km."],
      pt: ["Klerksdorp foi fundada em 1837.", "População: aprox. 190.000 habitantes.", "Produção de ouro na bacia de Witwatersrand: historicamente significativa.", "Altitude: 1.320 m acima do nível do mar.", "Precipitação anual: aprox. 500 mm.", "Distância para Joanesburgo: aprox. 180 km."],
      fr: ["Klerksdorp a été fondée en 1837.", "Population : env. 190 000 habitants.", "Production d'or dans le bassin du Witwatersrand : historiquement importante.", "Altitude : 1 320 m au-dessus du niveau de la mer.", "Précipitations annuelles : env. 500 mm.", "Distance jusqu'à Johannesburg : env. 180 km."],
