    facts: {
      de: ["Beherbergt den Hauptcampus der Nordwest-Universität.", "Gegründet im Jahr 1838."],
      hu: ["Az Északnyugati Egyetem fő kampuszának ad otthont.", "1838-ban alapították."],
      ro: ["Găzduiește campusul principal al Universității din Nord-Vest.", "Fondat în anul 1838."],
      en: ["Hosts the main campus of the North-West University.", "Founded in the year 1838."],
      es: ["Alberga el campus principal de la Universidad del Noroeste.", "Fundada en 1838."],
      pt: ["Alberga o campus principal da Universidade do Noroeste.", "Fundada em 1838."],
      fr: ["Abrite le campus principal de l'Université du Nord-Ouest.", "Fondée en 1838."],
    }, image: "/poi-images/southafrica-potchefstroom-cities-v2.webp",
    descriptionAdvanced: {
      de: "Potchefstroom, am Ufer des Mooi River gelegen, ist eine bedeutende Universitätsstadt in der Provinz Nordwest. Gegründet im Jahr 1838 von Andries Hendrik Potgieter, war sie die erste Hauptstadt der Südafrikanischen Republik (ZAR) und ist die zweitälteste Stadt in der ehemaligen Provinz Transvaal. Heute ist 'Potch', wie die Stadt lokal genannt wird, vor allem für den Hauptcampus der North-West University (NWU) bekannt, der Tausende von Studenten anzieht und eine lebendige akademische Atmosphäre schafft. Die Stadt ist zudem ein wichtiges sportliches Zentrum und beherbergt das High Performance Institute, wo viele internationale Athleten trainieren. Kulturell bietet Potchefstroom mit dem jährlichen Aardklop-Kunstfestival eines der größten Afrikaans-Kulturereignisse des Landes. Neben Bildung und Sport spielt der Bergbau im nahegelegenen Witwatersrand-Goldfeld sowie die Landwirtschaft eine tragende Rolle für die lokale Wirtschaft.",
      hu: "Potchefstroom a Mooi-folyó partján fekvő jelentős egyetemi város az Északnyugati tartományban. 1838-ban alapította Andries Hendrik Potgieter, és a Dél-afrikai Köztársaság (ZAR) első fővárosa volt, valamint a második legrégebbi város az egykori Transvaal tartományban. Ma 'Potch', ahogy a helyiek hívják, leginkább az Északnyugati Egyetem (NWU) fő kampuszáról ismert, amely hallgatók ezreit vonzza, és élénk akadémiai légkört teremt. A város emellett fontos sportközpont, itt található a High Performance Institute, ahol számos nemzetközi atléta edz. Kulturális szempontból Potchefstroom ad otthont az évenkénti Aardklop művészeti fesztiválnak, amely az ország egyik legnagyobb afrikaans nyelvű kulturális eseménye. Az oktatás és a sport mellett a közeli Witwatersrand aranylelőhelyek bányászata és a mezőgazdaság is meghatározó a helyi gazdaságban.",
      ro: "Potchefstroom, situat pe malurile râului Mooi, este un important oraș universitar din provincia North West. Fondat în 1838 de Andries Hendrik Potgieter, a fost prima capitală a Republicii Sud-Africane (ZAR) și este al doilea cel mai vechi oraș din fosta provincie Transvaal. Astăzi, „Potch”, așa cum este numit local, este cunoscut în principal pentru campusul principal al Universității North-West (NWU), care atrage mii de studenți și creează o atmosferă academică vibrantă. Orașul este, de asemenea, un centru sportiv important, găzduind High Performance Institute, unde se antrenează mulți atleți internaționali. Cultural, Potchefstroom găzduiește festivalul anual de artă Aardklop, unul dintre cele mai mari evenimente culturale în limba afrikaans din țară. Pe lângă educație și sport, mineritul de aur din apropiere și agricultura joacă un rol vital.",
      en: "Potchefstroom, nestled on the banks of the Mooi River, is a prominent academic and industrial city in the North West province. Established in 1838 by Andries Hendrik Potgieter, it served as the first capital of the South African Republic (ZAR) and remains the second oldest city in the former Transvaal province. Today, 'Potch,' as it is locally known, is synonymous with the main campus of North-West University (NWU), which fosters a vibrant youth culture and academic excellence. The city has also established itself as a premier sporting destination, home to the High Performance Institute where numerous international athletes conduct high-altitude training. Culturally, it hosts the annual Aardklop National Arts Festival, one of South Africa's most significant Afrikaans cultural events. Beyond education, the local economy is supported by gold mining within the Witwatersrand basin and a highly productive agricultural sector.",
      es: "Potchefstroom es una ciudad en la provincia del Noroeste en Sudáfrica, fundada en 1838 por los Voortrekkers. Se encuentra a orillas del río Mooi y tiene una población de unos 130.000 habitantes. Potchefstroom es un importante centro educativo y cultural con la Universidad del Noroeste, que cuenta con más de 50.000 estudiantes. La ciudad desempeñó un papel importante en la historia de las repúblicas bóer y fue la primera capital de la República Sudafricana. Económicamente, la ciudad se basa en la agricultura, la minería (oro y uranio) y el sector servicios. Los lugares de interés incluyen el jardín botánico y el Museo de Potchefstroom. La ciudad también tiene una escena deportiva vibrante, especialmente el rugby.",
      pt: "Potchefstroom é uma cidade na província do Noroeste na África do Sul, fundada em 1838 pelos Voortrekkers. Situa-se nas margens do rio Mooi e tem uma população de cerca de 130.000 habitantes. Potchefstroom é um importante centro educativo e cultural com a Universidade do Noroeste, que tem mais de 50.000 estudantes. A cidade desempenhou um papel importante na história das repúblicas bôeres e foi a primeira capital da República Sul-Africana. Economicamente, a cidade baseia-se na agricultura, mineração (ouro e urânio) e no setor de serviços. Atrações incluem o jardim botânico e o Museu Potchefstroom. A cidade também tem uma cena desportiva vibrante, especialmente o râguebi.",
      fr: "Potchefstroom est une ville de la province du Nord-Ouest en Afrique du Sud, fondée en 1838 par les Voortrekkers. Elle se trouve au bord de la rivière Mooi et compte une population d'environ 130 000 habitants. Potchefstroom est un important centre éducatif et culturel avec l'Université du Nord-Ouest, qui compte plus de 50 000 étudiants. La ville a joué un rôle important dans l'histoire des républiques boers et a été la première capitale de la République sud-africaine. Économiquement, la ville repose sur l'agriculture, l'exploitation minière (or et uranium) et le secteur des services. Les sites touristiques comprennent le jardin botanique et le musée de Potchefstroom. La ville possède également une scène sportive dynamique, notamment le rugby.",
    },
