      hu: ["1924-ben alapították, Johannes Nicolaas Britsről nevezték el", "Világviszonylatban is kiemelkedő platina- és krómlelőhely", "A citrusfélék és a dohánytermesztés fontos központja", "A Hartbeespoort-gát biztosítja a mezőgazdasági öntözővizet", "A történelmileg jelentős Magaliesberg-hegység lábánál fekszik", "Jelentős autóipari beszállító iparral rendelkezik"],
      ro: ["Fondat în 1924 și numit după Johannes Nicolaas Brits", "Centru global major pentru extracția platinei și a cromului", "Producător important de citrice, legume și tutun", "Sistem de irigații alimentat de barajul Hartbeespoort", "Situat la poalele munților pitorești Magaliesberg", "Găzduiește o industrie semnificativă de componente auto"],
      en: ["Established in 1924 on the farm Roode Kopjes", "Key global hub for platinum and chromium mining", "Major producer of citrus, vegetables, and tobacco products", "Irrigation sustained by the nearby Hartbeespoort Dam", "Situated at the foot of the Magaliesberg mountain range", "Significant center for the automotive component industry"],
      es: ["Brits fue fundada en 1920.", "Población: aprox. 80.000 habitantes.", "Planta Nissan: capacidad de producción de 50.000 vehículos anuales.", "Altitud: 1.000 m sobre el nivel del mar.", "Precipitación anual: unos 450 mm.", "Distancia a Pretoria: aprox. 50 km."],
      pt: ["Brits foi fundada em 1920.", "População: aprox. 80.000 habitantes.", "Fábrica da Nissan: capacidade de produção de 50.000 veículos anuais.", "Altitude: 1.000 m acima do nível do mar.", "Precipitação anual: cerca de 450 mm.", "Distância a Pretória: aprox. 50 km."],
