      en: ["Founded in 1864 and named after the Duke of Newcastle.", "Home to one of the largest steelworks operated by ArcelorMittal.", "Fort Amiel was established in 1876 as a military base.", "The city is situated at an altitude of 1,200 meters.", "Newcastle was the first town in South Africa to have a lighted main street.", "A major hub for rail-based coal transport in the region."],
      es: ["Newcastle fue fundada en 1864.", "Población: aprox. 400.000 habitantes.", "Producción de acero: 1 millón de toneladas al año.", "Altitud: 1.190 m sobre el nivel del mar.", "Precipitación anual: unos 800 mm.", "Distancia a Durban: aprox. 300 km."],
      pt: ["Newcastle foi fundada em 1864.", "População: aprox. 400.000 habitantes.", "Produção de aço: 1 milhão de toneladas por ano.", "Altitude: 1.190 m acima do nível do mar.", "Precipitação anual: cerca de 800 mm.", "Distância para Durban: aprox. 300 km."],
      fr: ["Newcastle a été fondée en 1864.", "Population : env. 400 000 habitants.", "Production d'acier : 1 million de tonnes par an.", "Altitude : 1 190 m au-dessus du niveau de la mer.", "Précipitations annuelles : environ 800 mm.", "Distance de Durban : env. 300 km."],
