      es: ["Fundada en 1880.", "Población: 84.000 (2011).", "Altitud: 1.700 m sobre el nivel del mar.", "Temperatura media: 17 °C.", "Precipitación anual: 700 mm.", "Producción de carbón en la región: aprox. 15 millones de toneladas al año."],
      pt: ["Fundada em 1880.", "População: 84.000 (2011).", "Altitude: 1.700 m acima do nível do mar.", "Temperatura média: 17 °C.", "Precipitação anual: 700 mm.", "Produção de carvão na região: aprox. 15 milhões de toneladas por ano."],
      fr: ["Fondée en 1880.", "Population : 84 000 (2011).", "Altitude : 1 700 m au-dessus du niveau de la mer.", "Température moyenne : 17 °C.", "Précipitations annuelles : 700 mm.", "Production de charbon dans la région : env. 15 millions de tonnes par an."],
