    name: { de: "Tzaneen", hu: "Tzaneen", ro: "Tzaneen", en: "Tzaneen"},
    image: "/poi-images/southafrica-tzaneen-cities-v2.webp",
    description: {
      de: "Die zweitgrößte Stadt in Limpopo liegt in einer üppig grünen, fruchtbaren Region, die tropische Früchte produziert.",
      hu: "Limpopo második legnagyobb városa egy buja zöld, termékeny vidéken fekszik, amely trópusi gyümölcsöket termeszt.",
      ro: "Al doilea oraș ca mărime din Limpopo este situat într-o regiune fertilă, verde, care produce fructe tropicale.",
      en: "The second largest town in Limpopo is situated in a lush, green, fertile region producing tropical fruits.",
      es: "La segunda ciudad más grande de Limpopo se encuentra en una región exuberante, verde y fértil que produce frutas tropicales.",
      pt: "A segunda maior cidade de Limpopo situa-se numa região exuberante, verde e fértil que produz fruta tropical.",
      fr: "La deuxième plus grande ville du Limpopo est située dans une région luxuriante, verte et fertile qui produit des fruits tropicaux.",
    },
    facts: {
      de: ["Gilt als eines der saubersten Städte in Südafrika.", "Hauptanbaugebiet für Avocados, Mangos und Tee."],
      hu: ["Dél-Afrika egyik legtisztább városaként tartják számon.", "Az avokádó, mangó és tea fő termesztési területe."],
      ro: ["Considerat unul dintre cele mai curate orașe din Africa de Sud.", "Zonă principală de cultivare pentru avocado, mango și ceai."],
      en: ["Regarded as one of the cleanest towns in South Africa.", "Major growing area for avocados, mangoes, and tea."],
      es: ["Considerada una de las ciudades más limpias de Sudáfrica.", "Principal zona de cultivo de aguacates, mangos y té."],
      pt: ["Considerada uma das cidades mais limpas da África do Sul.", "Principal zona de cultivo de abacates, mangas e chá."],
      fr: ["Considérée comme l'une des villes les plus propres d'Afrique du Sud.", "Principale zone de culture des avocats, des mangues et du thé."],
    }, image: "/poi-images/southafrica-tzaneen-cities-v2.webp",
    descriptionAdvanced: {
      de: "Tzaneen ist die zweitgrößte Stadt in der Provinz Limpopo und liegt im fruchtbaren Letaba-Tal am Fuße der Drakensberge. Die Stadt wurde offiziell im Jahr 1919 gegründet und hat sich seitdem zum wichtigsten Zentrum für subtropische Landwirtschaft in Südafrika entwickelt. Die Region ist bekannt für den großflächigen Anbau von Zitrusfrüchten, Mangos, Avocados, Bananen und Litschis sowie für bedeutende Tee- und Holzplantagen. Der Name Tzaneen leitet sich wahrscheinlich vom Nord-Sotho-Wort 'Tsaneng' ab, was so viel wie 'Sammelplatz' bedeutet. Geografisch ist die Gegend durch den nahegelegenen Tzaneen-Staudamm und die landschaftlich reizvolle Magoebaskloof-Passstraße geprägt. Aufgrund der hohen Niederschlagsraten und des warmen, frostfreien Klimas gilt die Region als eine der produktivsten Agrarzonen des Landes. Neben der Landwirtschaft spielt der Tourismus eine wachsende Rolle, da die Stadt als Tor zu den nördlichen Regionen des Krüger-Nationalparks dient.",
      hu: "Tzaneen Limpopo tartomány második legnagyobb városa, amely a termékeny Letaba-völgyben, a Drakensberg-hegység lábánál fekszik. A települést hivatalosan 1919-ben alapították, és azóta Dél-Afrika legfontosabb szubtrópusi mezőgazdasági központjává vált. A régió híres a kiterjedt citrusféle-, mangó-, avokádó-, banán- és licsiültetvényeiről, valamint jelentős tea- és faipari ültetvényekkel is rendelkezik. A Tzaneen név valószínűleg az északi sotho 'Tsaneng' szóból származik, amelynek jelentése 'gyülekezőhely'. Földrajzi arculatát a közeli Tzaneen-gát és a festői Magoebaskloof-hágó határozza meg. A magas csapadékmennyiség és a meleg, fagymentes éghajlat miatt az ország egyik legtermékenyebb mezőgazdasági övezetének tekintik. A mezőgazdaság mellett a turizmus is egyre fontosabb, mivel a város kapuként szolgál a Kruger Nemzeti Park északi területei felé.",
      ro: "Tzaneen este al doilea oraș ca mărime din provincia Limpopo, fiind situat în fertila vale Letaba, la poalele munților Drakensberg. Fondat oficial în anul 1919, orașul a devenit principalul centru al agriculturii subtropicale din Africa de Sud. Regiunea este celebră pentru culturile vaste de citrice, mango, avocado, banane și litchi, precum și pentru plantațiile de ceai și exploatările forestiere. Numele Tzaneen provine probabil din cuvântul sotho de nord 'Tsaneng', care înseamnă 'loc de adunare'. Din punct de vedere geografic, zona este marcată de prezența barajului Tzaneen și de spectaculoasa trecătoare Magoebaskloof. Datorită precipitațiilor bogate și a climatului cald, fără îngheț, regiunea este considerată una dintre cele mai productive zone agricole ale țării. Pe lângă agricultură, turismul joacă un rol esențial, orașul fiind o poartă de acces către regiunile nordice ale Parcului Național Kruger.",
      en: "Tzaneen is the second-largest town in the Limpopo province, nestled in the fertile Letaba Valley at the foot of the Drakensberg mountains. Formally established in 1919, it has evolved into South Africa's premier hub for subtropical agriculture. The region is renowned for its vast estates producing citrus, mangoes, avocados, bananas, and litchis, alongside significant tea plantations and forestry operations. The name Tzaneen is believed to be derived from the Northern Sotho word 'Tsaneng', meaning 'gathering place'. Geographically, the landscape is defined by the massive Tzaneen Dam and the scenic Magoebaskloof Pass. Due to high rainfall and a warm, frost-free climate, it is regarded as one of the most productive agricultural zones in the country. Beyond farming, tourism is a vital industry, as the town serves as a convenient gateway to the northern sections of the Kruger National Park.",
      es: "Tzaneen es una ciudad en la provincia sudafricana de Limpopo, situada al pie de las montañas Wolkberg. Fue fundada en 1903 y es un importante centro de cultivo de frutas y verduras, especialmente plátanos, aguacates, mangos y cítricos. La región de Tzaneen goza de un clima subtropical con abundantes precipitaciones. La ciudad tiene unos 20.000 habitantes (censo de 2011), pero el área metropolitana es mayor. La presa de Tzaneen, un embalse, suministra agua a la agricultura. La zona también es conocida por sus reservas naturales como Magoebaskloof y las cataratas Debengeni. Tzaneen es una puerta de entrada al Parque Nacional Kruger, que se encuentra a unos 100 km al este. La economía local está marcada por la agroindustria y el turismo.",
      pt: "Tzaneen é uma cidade na província sul-africana de Limpopo, situada ao pé das montanhas Wolkberg. Foi fundada em 1903 e é um importante centro de cultivo de fruta e legumes, especialmente bananas, abacates, mangas e citrinos. A região de Tzaneen desfruta de um clima subtropical com chuvas abundantes. A cidade tem cerca de 20.000 habitantes (censo de 2011), mas a área metropolitana é maior. A barragem de Tzaneen, um reservatório, fornece água para a agricultura. A zona é também conhecida pelas suas reservas naturais como Magoebaskloof e as cascatas Debengeni. Tzaneen é uma porta de entrada para o Parque Nacional Kruger, que se situa a cerca de 100 km a leste. A economia local é marcada pela agroindústria e pelo turismo.",
      fr: "Tzaneen est une ville de la province sud-africaine du Limpopo, située au pied des montagnes Wolkberg. Elle a été fondée en 1903 et est un important centre de culture de fruits et légumes, notamment les bananes, les avocats, les mangues et les agrumes. La région de Tzaneen bénéficie d'un climat subtropical avec des précipitations abondantes. La ville compte environ 20 000 habitants (recensement de 2011), mais l'agglomération est plus grande. Le barrage de Tzaneen, un réservoir, fournit de l'eau à l'agriculture. La région est également connue pour ses réserves naturelles comme Magoebaskloof et les chutes Debengeni. Tzaneen est une porte d'entrée vers le parc national Kruger, qui se trouve à environ 100 km à l'est. L'économie locale est marquée par l'agro-industrie et le tourisme.",
    },
