    facts: {
      de: ["Heimat von Makapansgat, einer bedeutenden prähistorischen Fundstätte.", "Wichtiges Zentrum des Platinbergbaus."],
      hu: ["Makapansgat, egy jelentős őskori lelőhely otthona.", "A platinabányászat fontos központja."],
      ro: ["Sediul Makapansgat, un important sit preistoric.", "Centru important al mineritului de platina."],
      en: ["Home to Makapansgat, a major prehistoric archaeological site.", "Important center of platinum mining."],
      es: ["Hogar de Makapansgat, un importante yacimiento prehistórico.", "Importante centro de minería de platino."],
      pt: ["Lar de Makapansgat, um importante sítio pré-histórico.", "Importante centro de mineração de platina."],
      fr: ["Abrite Makapansgat, un site préhistorique important.", "Important centre d'exploitation minière du platine."],
    }, image: "/poi-images/southafrica-mokopane-cities-v2.webp",
    descriptionAdvanced: {
      de: "Mokopane, bis 2003 als Potgietersrus bekannt, liegt in der Provinz Limpopo am Fuße des Waterberg-Massivs. Die Stadt wurde 1852 von den Voortrekkern gegründet und ist nach dem Häuptling Mokopane benannt. Die Region ist von enormer historischer Bedeutung, da sich in unmittelbarer Nähe die Makapansgat-Höhlen befinden, die Teil des UNESCO-Welterbes 'Wiege der Menschheit' sind und Fossilien früher Hominiden enthalten. Wirtschaftlich ist Mokopane heute eines der bedeutendsten Zentren für den Platinbergbau weltweit, insbesondere durch die Operationen der Anglo American Platinum Mine. Neben dem Bergbau prägt eine produktive Landwirtschaft die Umgebung, wobei der Fokus auf dem Anbau von Tabak, Baumwolle, Mais und Zitrusfrüchten sowie der Rinderzucht liegt. Die Stadt profitiert zudem von ihrer Lage an der Nationalstraße N1, die Pretoria mit der Grenze zu Simbabwe verbindet. Das Klima ist subtropisch mit heißen Sommern und milden Wintern, was die ganzjährige landwirtschaftliche Nutzung ermöglicht.",
      hu: "Mokopane, amely 2003-ig Potgietersrus néven volt ismert, Limpopo tartományban, a Waterberg-hegység lábánál fekszik. A várost 1852-ben alapították a voortrekkerek, jelenlegi nevét pedig Mokopane törzsfőnökről kapta. A régió kiemelkedő történelmi jelentőséggel bír, mivel a közvetlen közelében találhatók a Makapansgat-barlangok, amelyek az UNESCO Világörökség részét képező „Az emberiség bölcsője” helyszínhez tartoznak, és fontos hominida fosszíliákat őriznek. Gazdaságilag Mokopane ma a világ egyik legjelentősebb platinabányászati központja, különösen az Anglo American Platinum bányái révén. A bányászat mellett a mezőgazdaság is meghatározó, a dohány, a gyapot, a kukorica és a citrusfélék termesztése, valamint a szarvasmarha-tenyésztés a fő ágazatok. A város kedvező elhelyezkedése az N1-es autópálya mentén fontos tranzitcsomóponttá teszi Pretoria és a zimbabwei határ között.",
      ro: "Mokopane, cunoscut sub numele de Potgietersrus până în 2003, este situat în provincia Limpopo, la poalele masivului Waterberg. Orașul a fost fondat în 1852 de către voortrekkers și poartă numele căpeteniei locale Mokopane. Regiunea are o importanță istorică imensă datorită peșterilor Makapansgat din apropiere, care fac parte din Patrimoniul Mondial UNESCO „Leagănul Omenirii” și conțin fosile de hominizi timpurii. Din punct de vedere economic, Mokopane este astăzi unul dintre cele mai importante centre de extracție a platinei la nivel mondial, în special prin operațiunile minei Anglo American Platinum. Pe lângă minerit, agricultura este o ramură de bază, cu un accent pe cultivarea tutunului, bumbacului, porumbului și citricelor, precum și pe creșterea vitelor. Orașul beneficiază de poziția sa strategică pe autostrada N1, care leagă Pretoria de frontiera cu Zimbabwe, favorizând comerțul regional.",
      en: "Mokopane, formerly known as Potgietersrus until 2003, is situated in the Limpopo province at the foot of the Waterberg Mountains. Founded in 1852 by the Voortrekkers, it was later renamed to honor the local chief Mokopane. The area is of immense paleoanthropological significance due to the nearby Makapansgat Caves, part of the UNESCO World Heritage Site 'Cradle of Humankind', which houses fossils of early hominids. Economically, Mokopane is one of the world's most significant platinum mining hubs, driven largely by the massive operations of Anglo American Platinum. Agriculture also plays a fundamental role in the local economy, with the surrounding plains dedicated to farming tobacco, cotton, maize, and citrus, as well as cattle ranching. The town's location on the N1 national road, the primary artery connecting Pretoria to the Zimbabwean border, ensures its status as a vital transit and commercial center.",
      es: "Mokopane, antiguamente Potgietersrus, es una ciudad de la provincia sudafricana de Limpopo. Fue fundada en 1854 por los Voortrekkers y llamada así en honor a Piet Potgieter, un líder bóer que murió en un conflicto con los Ndebele. En 2010, la ciudad pasó a llamarse oficialmente Mokopane, en honor a un jefe local Ndebele. Es un centro minero, especialmente de platino, cromo y otros minerales. La agricultura incluye maíz y ganadería. La población es de unos 30.000 habitantes (censo de 2011), muchos de los cuales trabajan en las minas circundantes. La zona es rica en sitios arqueológicos, incluido el valle de Makapan, que es Patrimonio de la Humanidad por la UNESCO y alberga fósiles de homínidos tempranos. Mokopane está en la carretera nacional N11 y sirve de puerta de entrada a la Reserva de la Biosfera de Waterberg.",
      pt: "Mokopane, antigamente Potgietersrus, é uma cidade na província sul-africana de Limpopo. Foi fundada em 1854 pelos Voortrekkers e nomeada em homenagem a Piet Potgieter, um líder boer que morreu num conflito com os Ndebele. Em 2010, a cidade foi oficialmente renomeada para Mokopane, em honra de um chefe local Ndebele. É um centro mineiro, especialmente de platina, crómio e outros minerais. A agricultura inclui milho e pecuária. A população é de cerca de 30.000 habitantes (censo de 2011), muitos dos quais trabalham nas minas circundantes. A zona é rica em locais arqueológicos, incluindo o Vale de Makapan, que é Património Mundial da UNESCO e alberga fósseis de hominídeos antigos. Mokopane situa-se na estrada nacional N11 e serve de porta de entrada para a Reserva da Biosfera de Waterberg.",
      fr: "Mokopane, anciennement Potgietersrus, est une ville de la province sud-africaine du Limpopo. Elle a été fondée en 1854 par les Voortrekkers et nommée d'après Piet Potgieter, un chef boer mort lors d'un conflit avec les Ndebele. En 2010, la ville a été officiellement rebaptisée Mokopane, en l'honneur d'un chef local Ndebele. C'est un centre minier, notamment pour le platine, le chrome et d'autres minéraux. L'agriculture comprend le maïs et l'élevage. La population est d'environ 30 000 habitants (recensement de 2011), dont beaucoup travaillent dans les mines environnantes. La région est riche en sites archéologiques, dont la vallée de Makapan, classée au patrimoine mondial de l'UNESCO et abritant des fossiles d'hominidés primitifs. Mokopane se situe sur la route nationale N11 et sert de porte d'entrée à la réserve de biosphère du Waterberg.",
    },
