      en: ["Founded in 1852 by Voortrekker settlers", "Renamed from Potgietersrus to Mokopane in 2003", "Site of one of the largest open-pit platinum mines", "Nearby Makapansgat is a UNESCO World Heritage Site", "Major production center for citrus, cotton, and tobacco", "Key stop on the N1 highway between Pretoria and Zimbabwe"],
