      pt: ["Fundada em 1854", "População: 30.000 (2011)", "Vale de Makapan: fósseis de 3,3 milhões de anos", "Altitude: 1.150 m acima do nível do mar", "Produção de platina na região: aprox. 1 milhão de onças por ano", "Superfície da Reserva da Biosfera de Waterberg: 4.000 km²"],
