    name: { de: "Thohoyandou", hu: "Thohoyandou", ro: "Thohoyandou", en: "Thohoyandou"},
    image: "/poi-images/southafrica-thohoyandou-cities-v2.webp",
    description: {
      de: "Die ehemalige Hauptstadt des Venda-Homelands ist heute das kulturelle und kommerzielle Zentrum der Region Vhembe.",
      hu: "A Venda bantusztán korábbi fővárosa ma a Vhembe régió kulturális és kereskedelmi központja.",
      ro: "Fosta capitală a bantustanului Venda este astăzi centrul cultural și comercial al regiunii Vhembe.",
      en: "The former capital of the Venda homeland is today the cultural and commercial center of the Vhembe region.",
      es: "La antigua capital del territorio de Venda es hoy el centro cultural y comercial de la región de Vhembe.",
      pt: "A antiga capital do território de Venda é hoje o centro cultural e comercial da região de Vhembe.",
      fr: "L'ancienne capitale du territoire de Venda est aujourd'hui le centre culturel et commercial de la région de Vhembe.",
    },
    facts: {
      de: ["Der Name bedeutet 'Kopf des Elefanten'.", "Sitz der Universität von Venda."],
      hu: ["A név jelentése 'Az elefánt feje'.", "A Venda Egyetem székhelye."],
      ro: ["Numele înseamnă 'Capul elefantului'.", "Sediul Universității din Venda."],
      en: ["The name means 'Head of the elephant'.", "Seat of the University of Venda."],
      es: ["El nombre significa 'cabeza de elefante'.", "Sede de la Universidad de Venda."],
      pt: ["O nome significa 'cabeça de elefante'.", "Sede da Universidade de Venda."],
      fr: ["Le nom signifie « tête d'éléphant ». ", "Siège de l'université de Venda."],
    }, image: "/poi-images/southafrica-thohoyandou-cities-v2.webp",
    descriptionAdvanced: {
      de: "Thohoyandou ist das administrative Zentrum des Distrikts Vhembe in der Provinz Limpopo und war einst die Hauptstadt des ehemaligen Homeland-Staates Venda. Die Stadt wurde Ende der 1970er Jahre planmäßig angelegt und nach dem legendären König Thohoyandou benannt, dessen Name 'Kopf des Elefanten' bedeutet. Die Region ist das kulturelle Herz des Venda-Volkes und bekannt für ihre üppige, subtropische Vegetation sowie die fruchtbaren Böden. Wirtschaftlich wird die Gegend durch den Anbau von Bananen, Mangos, Avocados und Macadamia-Nüssen geprägt. Thohoyandou beherbergt zudem die Universität von Venda, eine bedeutende Bildungseinrichtung in der Region. Geografisch liegt die Stadt in der Nähe des Soutpansberg-Gebirges und des Punda Maria Tores zum Krüger-Nationalpark. Die lokale Kultur spiegelt sich in traditioneller Kunst, Holzschnitzereien und Musik wider, was Thohoyandou zu einem wichtigen kulturellen Zentrum im Norden Südafrikas macht.",
      hu: "Thohoyandou a dél-afrikai Limpopo tartomány Vhembe kerületének közigazgatási központja, amely egykor az egykori Venda homeland fővárosa volt. A várost az 1970-es évek végén építették tervszerűen, és a legendás Thohoyandou királyról nevezték el, akinek neve „elefántfejet” jelent. A régió a venda nép kulturális szíve, amely buja szubtrópusi vegetációjáról és rendkívül termékeny talajáról ismert. Gazdaságilag a területet a banán-, mangó-, avokádó- és makadámdió-ültetvények dominálják. Thohoyandou ad otthont a Venda Egyetemnek, amely a térség egyik legfontosabb oktatási intézménye. Földrajzilag a Soutpansberg-hegység közelében fekszik, és fontos kiindulópont a Kruger Nemzeti Park Punda Maria kapuja felé. A helyi kultúra a hagyományos művészetekben, a fafaragásban és a zenében tükröződik, ami a várost Észak-Dél-Afrika egyik legfontosabb kulturális csomópontjává teszi.",
      ro: "Thohoyandou este centrul administrativ al districtului Vhembe din provincia Limpopo, servind în trecut drept capitală a fostului stat Venda. Orașul a fost construit planificat la sfârșitul anilor 1970 și poartă numele legendarului rege Thohoyandou, al cărui nume se traduce prin „cap de elefant”. Regiunea reprezintă inima culturală a poporului Venda și este renumită pentru vegetația subtropicală luxuriantă și solurile sale fertile. Economia locală este dominată de plantații extinse de banane, mango, avocado și nuci de macadamia. Thohoyandou găzduiește, de asemenea, Universitatea din Venda, o instituție de învățământ superior crucială pentru nordul țării. Din punct de vedere geografic, orașul este situat în apropierea munților Soutpansberg și reprezintă un punct important de acces către poarta Punda Maria a Parcului Național Kruger. Cultura locală vibrantă este evidențiată prin sculpturi în lemn și muzică tradițională.",
      en: "Thohoyandou is the administrative capital of the Vhembe District in the Limpopo province and previously served as the capital of the former Venda bantustan. The town was purposefully established in the late 1970s and named after King Thohoyandou, whose name means 'head of the elephant' in the Venda language. The region is the cultural heartland of the Venda people, characterized by lush subtropical vegetation and highly fertile soils. The local economy revolves around the intensive cultivation of bananas, mangoes, avocados, and macadamia nuts. Thohoyandou is also home to the University of Venda, a significant academic institution in the region. Geographically, the town is located near the Soutpansberg mountain range and serves as a major gateway to the Punda Maria gate of the Kruger National Park. The city remains a vibrant center for traditional Venda art, woodcarving, and music, reflecting its deep historical and cultural roots.",
      es: "Thohoyandou es la capital de la región tradicional Venda en la provincia sudafricana de Limpopo. La ciudad fue desarrollada después de 1960 como centro administrativo del antiguo territorio de Venda y lleva el nombre del legendario rey Thohoyandou, que reinó en el siglo XVIII. La ciudad tiene unos 70.000 habitantes (censo de 2011). Thohoyandou es un centro de comercio, agricultura y turismo. En los alrededores se cultivan frutas tropicales, té y madera. Las cercanas montañas Soutpansberg ofrecen rutas de senderismo y cascadas. La Universidad de Venda (UNIVEN) tiene su sede aquí y contribuye a la economía local. Culturalmente, la ciudad es rica en tradiciones Venda, incluyendo cerámica y música.",
      pt: "Thohoyandou é a capital da região tradicional Venda na província sul-africana de Limpopo. A cidade foi desenvolvida após 1960 como centro administrativo do antigo território de Venda e tem o nome do lendário rei Thohoyandou, que reinou no século XVIII. A cidade tem cerca de 70.000 habitantes (censo de 2011). Thohoyandou é um centro de comércio, agricultura e turismo. Nas redondezas cultivam-se frutas tropicais, chá e madeira. As próximas montanhas Soutpansberg oferecem percursos pedestres e cascatas. A Universidade de Venda (UNIVEN) tem aqui a sua sede e contribui para a economia local. Culturalmente, a cidade é rica em tradições Venda, incluindo cerâmica e música.",
      fr: "Thohoyandou est la capitale de la région traditionnelle Venda dans la province sud-africaine du Limpopo. La ville a été développée après 1960 en tant que centre administratif de l'ancien territoire de Venda et tire son nom du légendaire roi Thohoyandou, qui a régné au XVIIIe siècle. La ville compte environ 70 000 habitants (recensement de 2011). Thohoyandou est un centre de commerce, d'agriculture et de tourisme. Des fruits tropicaux, du thé et du bois sont cultivés dans les environs. Les montagnes Soutpansberg toutes proches offrent des sentiers de randonnée et des cascades. L'université de Venda (UNIVEN) a son siège ici et contribue à l'économie locale. Sur le plan culturel, la ville est riche en traditions Venda, notamment dans la poterie et la musique.",
    },
