      en: ["Capital of the former Venda republic until 1994", "Named after King Thohoyandou, meaning 'elephant head'", "Home to the University of Venda (UNIVEN)", "Significant hub for the macadamia nut industry", "Largest commercial and shopping center in northern Limpopo", "Primary gateway to the Kruger National Park's Punda Maria gate"],
      es: ["Fundada en la década de 1960", "Población: 70.000 (2011)", "Universidad de Venda: fundada en 1982, más de 10.000 estudiantes", "Altitud: 700 m sobre el nivel del mar", "Pico más alto de Soutpansberg: 1.750 m", "Temperatura media: 22 °C"],
