      fr: ["Fondée dans les années 1960", "Population : 70 000 (2011)", "Université de Venda : fondée en 1982, plus de 10 000 étudiants", "Altitude : 700 m au-dessus du niveau de la mer", "Plus haut sommet de Soutpansberg : 1 750 m", "Température moyenne : 22 °C"],
